name: CI
on:
  push:
    branches: [main]
  pull_request:
  # A push does not always get scheduled — a platform incident can drop the run
  # while leaving the release workflow to report a startup failure — and without a
  # manual trigger there is no way to verify a commit after the fact.
  workflow_dispatch:
permissions:
  contents: read
jobs:
  test:
    runs-on: ubuntu-latest
    # The analytical reports build SQL by hand, so the suite runs them against a real
    # PostgreSQL instance. A syntax or type error there is invisible to unit tests.
    services:
      postgres:
        image: postgres:17-alpine
        env:
          POSTGRES_PASSWORD: ci
          POSTGRES_DB: momento
        ports: ["5432:5432"]
        options: >-
          --health-cmd "pg_isready -U postgres -d momento"
          --health-interval 5s
          --health-timeout 3s
          --health-retries 20
    env:
      MOMENTO_TEST_POSTGRES_DSN: postgres://postgres:ci@127.0.0.1:5432/momento?sslmode=disable
    steps:
      - uses: actions/checkout@v6
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v6
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: |
            web/package-lock.json
            sdk/package-lock.json
      # The reports answer by running their independent reads at the same time, so
      # the handlers that build them share variables across goroutines. The race
      # detector is what says that sharing is correct; without it a report that
      # occasionally returned a half-filled answer would look like a flaky test.
      # It costs about ninety seconds here, because these tests wait on a database
      # rather than on the CPU.
      - run: go test -race ./cmd/... ./internal/...
      - run: go vet ./cmd/... ./internal/...
      - run: go run golang.org/x/vuln/cmd/govulncheck@latest ./cmd/... ./internal/...
      - run: npm ci && npm audit && npm run typecheck && npm test && npm run build
        working-directory: sdk
      - run: npm ci && npm audit && npm run lint && npm test && npm run build
        working-directory: web
      - name: Build production image
        run: docker build --build-arg VERSION=ci --build-arg COMMIT=${GITHUB_SHA::12} -t momento:ci .

// 보존 정책 저장 Alert 을 실제 dist + 진짜 APIError 로 확인한다.
// 에러 객체는 손으로 만든 대역이 아니라 client.ts 의 api() 가 HTTP 응답에서 만든다.
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import puppeteer from "puppeteer-core";

const DIST = process.argv[2];
const TYPES = {
  ".html": "text/html",
  ".js": "text/javascript",
  ".css": "text/css",
  ".svg": "image/svg+xml",
  ".json": "application/json",
  ".woff2": "font/woff2",
};

// 다음 PUT /api/v1/sites/{id}/retention 이 돌려줄 응답. null 이면 성공.
let nextRefusal = null;
// 마지막 PUT 이 실제로 실려 보낸 본문 — 빈 칸이 null 로 가는지 보려고 받아 둔다.
let lastPutBody = null;

const ME = {
  id: "00000000-0000-0000-0000-000000000001",
  email: "admin@example.com",
  display_name: "관리자",
  department: "IT",
  organization_name: "Momento",
  role: "super_admin",
};

const SITES = [
  {
    id: "00000000-0000-0000-0000-0000000000a1",
    site_id: "prd",
    name: "PRD",
    service_name: "Momento",
    allowed_domains: ["example.com"],
    session_timeout_minutes: 30,
    timezone: "Asia/Seoul",
    engagement_threshold_seconds: 10,
    active: true,
    tracking_key_prefix: "pk_test",
    server_api_key_prefix: "sk_test",
    workspace: "default",
    organization: "Momento",
    created_at: "2026-01-01T00:00:00Z",
  },
];

// advanced_analytics.go 의 getRetentionPolicy 가 돌려주는 꼴.
const POLICY = {
  policy: {
    raw_event_months: 13,
    session_months: 25,
    aggregation_months: 36,
    realtime_hours: 24,
    debug_days: 7,
  },
  updated_at: "2026-01-01T00:00:00Z",
  last_run: null,
};

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  const p = url.pathname;
  const json = (status, body) => {
    res.writeHead(status, { "content-type": "application/json" });
    res.end(JSON.stringify(body));
  };
  if (p === "/api/v1/me") return json(200, ME);
  if (p === "/api/v1/sites") return json(200, SITES);
  if (p === "/api/v1/version") return json(200, { version: "test" });
  if (/^\/api\/v1\/sites\/[^/]+\/retention$/.test(p)) {
    if (req.method === "GET") return json(200, POLICY);
    if (req.method === "PUT") {
      let chunks = "";
      req.on("data", (c) => (chunks += c));
      return req.on("end", () => {
        try {
          lastPutBody = JSON.parse(chunks);
        } catch {
          lastPutBody = { parseError: chunks };
        }
        const r = nextRefusal;
        if (!r) return json(200, { updated: true });
        // writeError 와 같은 꼴: {"error":{"code":…,"message":…}}
        json(r.status, { error: { code: r.code, message: r.message } });
      });
    }
  }
  if (p.startsWith("/api/")) return json(200, []);
  let file = path.join(DIST, p === "/" ? "index.html" : p.slice(1));
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory())
    file = path.join(DIST, "index.html");
  res.writeHead(200, {
    "content-type": TYPES[path.extname(file)] || "application/octet-stream",
  });
  res.end(fs.readFileSync(file));
});

await new Promise((r) => server.listen(0, r));
const base = `http://127.0.0.1:${server.address().port}`;

const PG_MARKERS = [
  "SQLSTATE",
  "violates",
  "relation",
  "no rows in result set",
];
const RETENTION_FK_PGX =
  'ERROR: insert or update on table "retention_policies" violates foreign key constraint "retention_policies_site_id_fkey" (SQLSTATE 23503)';
const RETENTION_DOWN_PGX =
  "failed to connect to `host=localhost user=momento database=momento`: dial error: connection refused";

// 영문 컬럼명은 어느 안내 본문에도 남아서는 안 된다.
const COLUMNS = [
  "raw_event_months",
  "session_months",
  "aggregation_months",
  "realtime_hours",
  "debug_days",
];

// 칸을 범위 밖 값으로 채우고, 서버는 validateRetention 이 실제로 내는 문장을
// 글자 그대로 돌려준다(advanced_analytics.go:82·85·88·91·94).
function fieldCase(label, screenLabel, value, serverMessage, mustSay) {
  return {
    label,
    fill: { [screenLabel]: value },
    refusal: {
      status: 400,
      code: "INVALID_RETENTION",
      message: serverMessage,
    },
    checks: (got) => {
      const errs = [];
      const leakedCols = COLUMNS.filter((c) => got.body.includes(c));
      if (leakedCols.length)
        errs.push(`본문에 샌 영문 컬럼명: ${leakedCols.join(", ")}`);
      if (/must be|between/.test(got.body))
        errs.push("서버의 영문 문장이 본문에 남았다");
      if (!got.body.includes(`「${screenLabel}」`))
        errs.push(`본문이 「${screenLabel}」 를 가리키지 않는다`);
      for (const piece of mustSay)
        if (!got.body.includes(piece))
          errs.push(`허용 범위 "${piece}" 가 본문에 없다`);
      if (got.detail) errs.push(`detail 이 불필요하게 남았다: ${got.detail}`);
      return errs;
    },
  };
}

function leaked(got, raw) {
  const errs = [];
  const found = PG_MARKERS.filter((m) => got.body.includes(m));
  if (found.length) errs.push(`본문에 샌 Postgres 표지: ${found.join(", ")}`);
  if (got.detail !== raw) errs.push(`detail 에 서버 원문이 없다: ${got.detail}`);
  if (/이미 (있는|등록된|존재)/.test(got.body))
    errs.push("500 을 중복이라고 설명한다");
  return errs;
}

const CASES = [
  fieldCase(
    "Raw Event 범위 밖 (400)",
    "Raw Event (개월)",
    "999",
    "raw_event_months must be between 1 and 120",
    ["1개월", "120개월"],
  ),
  fieldCase(
    "Session 요약 범위 밖 (400)",
    "Session 요약 (개월)",
    "999",
    "session_months must be between 1 and 120",
    ["1개월", "120개월"],
  ),
  fieldCase(
    "Aggregation 범위 밖 (400)",
    "Aggregation (개월)",
    "99999",
    "aggregation_months must be null or between 1 and 1200",
    ["비워", "1개월", "1200개월"],
  ),
  fieldCase(
    "Realtime 범위 밖 (400)",
    "Realtime (시간)",
    "999",
    "realtime_hours must be between 1 and 168",
    ["1시간", "168시간"],
  ),
  fieldCase(
    "Debugger / Dead Letter 범위 밖 (400)",
    "Debugger / Dead Letter (일)",
    "999",
    "debug_days must be between 1 and 90",
    ["1일", "90일"],
  ),
  {
    label: "저장 실패 — 외래키 (500)",
    fill: { "Raw Event (개월)": "12" },
    refusal: {
      status: 500,
      code: "RETENTION_SAVE_FAILED",
      message: RETENTION_FK_PGX,
    },
    checks: (got) => leaked(got, RETENTION_FK_PGX),
  },
  {
    label: "저장 실패 — DB 장애 (500)",
    fill: { "Raw Event (개월)": "12" },
    refusal: {
      status: 500,
      code: "RETENTION_SAVE_FAILED",
      message: RETENTION_DOWN_PGX,
    },
    checks: (got) => leaked(got, RETENTION_DOWN_PGX),
  },
  {
    label: "사이트 없음 (404)",
    fill: { "Raw Event (개월)": "12" },
    refusal: { status: 404, code: "UNKNOWN_SITE", message: "site not found" },
    checks: (got) => {
      const errs = [];
      if (got.body.includes("site not found"))
        errs.push("서버 영문이 본문에 그대로 올라왔다");
      if (!/새로 고침|새로 고친/.test(got.body))
        errs.push("새로 고침을 권하지 않는다");
      if (got.detail) errs.push(`detail 이 불필요하게 남았다: ${got.detail}`);
      return errs;
