  headless: true,
  args: ["--no-sandbox", "--disable-dev-shm-usage"],
});
// 칸을 채우면 useUnsavedWarning 이 beforeunload 를 걸어 같은 탭의 재이동이
// 막힌다(components/useUnsavedWarning.ts). 앱 동작을 건드리지 않으려고 사례마다
// 새 탭을 쓴다 — 새 탭에는 그 핸들러가 없다.
async function openRetention() {
  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 1200 });
  await page.goto(`${base}/admin?section=retention`, {
    waitUntil: "networkidle2",
  });
  await page.waitForFunction(
    () =>
      [...document.querySelectorAll("button")].some(
        (b) => b.textContent.trim() === "보존 정책 저장",
      ),
    { timeout: 20000 },
  );
  return page;
}

const FILL = (pairs) => {
  const set = (el, v) => {
    const d = Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype,
      "value",
    );
    d.set.call(el, v);
    el.dispatchEvent(new Event("input", { bubbles: true }));
  };
  const labels = [...document.querySelectorAll("label")];
  const byLabel = (text) => {
    const l = labels.find((x) => x.textContent.trim() === text);
    return l && document.getElementById(l.getAttribute("for"));
  };
  for (const [label, value] of pairs) {
    const el = byLabel(label);
    if (!el)
      return { ok: false, labels: labels.map((l) => l.textContent.trim()) };
    set(el, value);
  }
  return { ok: true };
};

const CLICK_SAVE = () => {
  const b = [...document.querySelectorAll("button")].find(
    (x) => x.textContent.trim() === "보존 정책 저장" && !x.disabled,
  );
  if (!b) return false;
  b.click();
