};

const READ_ALERT = () => {
  // 화면 위쪽 info Alert 을 집지 않도록 severity=error 만 읽는다.
  const a = [...document.querySelectorAll('[role="alert"]')].find((x) =>
    x.className.includes("Error"),
  );
  if (!a) return null;
  const ps = [...a.querySelectorAll("p,span")].map((x) => x.textContent.trim());
  // 고치기 전 Alert 은 문구를 <p>/<span> 없이 바로 넣으므로, 요소가 없으면
  // Alert 전체 텍스트가 본문이다 — 그래야 옛 모양의 영문이 실제로 읽힌다.
  if (!ps.length) return { body: a.innerText.trim(), detail: null };
  return { body: ps[0] || "", detail: ps[1] || null };
};

let failures = 0;
for (const c of CASES) {
  nextRefusal = c.refusal;
  const page = await openRetention();
  const filled = await page.evaluate(FILL, Object.entries(c.fill));
  if (!filled.ok) {
    console.log(
      `FAIL ${c.label}: 입력 칸을 못 찾음 — ${JSON.stringify(filled.labels)}`,
    );
    failures++;
    await page.close();
    continue;
  }
  const clicked = await page.evaluate(CLICK_SAVE);
  if (!clicked) {
    console.log(`FAIL ${c.label}: 「보존 정책 저장」 버튼을 누를 수 없다`);
    failures++;
    await page.close();
    continue;
  }
  let got;
  try {
    await page.waitForFunction(
      () =>
        [...document.querySelectorAll('[role="alert"]')].some((x) =>
          x.className.includes("Error"),
        ),
      { timeout: 20000 },
    );
    got = await page.evaluate(READ_ALERT);
  } catch {
    console.log(`FAIL ${c.label}: 오류 Alert 이 나타나지 않았다`);
    failures++;
    await page.close();
    continue;
  }
  const errs = c.checks(got);
  console.log(
    `${errs.length ? "FAIL" : "ok  "} ${c.label}\n      body=${JSON.stringify(got.body)}\n      detail=${JSON.stringify(got.detail)}`,
  );
  for (const e of errs) console.log(`      -> ${e}`);
  failures += errs.length ? 1 : 0;
  await page.close();
}

// 과제서가 코드로만 확인하고 브라우저로는 확인하지 않은 것: 「Aggregation (개월)」 을
// 비우면 null 이 가고 validateRetention 이 통과시킨다. 서버를 성공으로 두고
// 실제로 실려 간 본문을 읽는다.
nextRefusal = null;
lastPutBody = null;
const page = await openRetention();
const blanked = await page.evaluate(FILL, [["Aggregation (개월)", ""]]);
if (!blanked.ok) {
  console.log("FAIL 빈 Aggregation: 칸을 못 찾음");
  failures++;
} else if (!(await page.evaluate(CLICK_SAVE))) {
  console.log("FAIL 빈 Aggregation: 저장 버튼을 누를 수 없다");
  failures++;
} else {
  await page.waitForFunction(() => true);
  const deadline = Date.now() + 15000;
  while (!lastPutBody && Date.now() < deadline)
    await new Promise((r) => setTimeout(r, 100));
  const errs = [];
  if (!lastPutBody) errs.push("PUT 이 서버에 도달하지 않았다");
  else if (lastPutBody.aggregation_months !== null)
    errs.push(
      `aggregation_months 가 null 이 아니다: ${JSON.stringify(lastPutBody.aggregation_months)}`,
    );
  const alert = await page.evaluate(READ_ALERT);
  if (alert) errs.push(`성공인데 오류 Alert 이 떴다: ${alert.body}`);
  console.log(
    `${errs.length ? "FAIL" : "ok  "} 빈 Aggregation 은 null 로 가고 서버가 통과시킨다\n      put=${JSON.stringify(lastPutBody)}`,
  );
  for (const e of errs) console.log(`      -> ${e}`);
  failures += errs.length ? 1 : 0;
}

await browser.close();
server.close();
console.log(
  failures ? `\nRESULT: 기대와 다름 (${failures}건)` : "\nRESULT: 전부 기대대로",
);
process.exit(failures ? 1 : 0);

